const matchScore=(x:Obj)=>x.status==='final'?`${x.homeGoals}–${x.awayGoals}${x.homePenalties!=null?` (pên. ${x.homePenalties}–${x.awayPenalties})`:''}`:'—';
const standings=teamList.map((team:Obj)=>{let played=0,w=0,d=0,l=0,gf=0,ga=0;matches.filter((x:Obj)=>t?.format==='league'&&x.status==='final'&&(x.homeId===team.id||x.awayId===team.id)).forEach((x:Obj)=>{played++;const a=x.homeId===team.id?x.homeGoals:x.awayGoals,b=x.homeId===team.id?x.awayGoals:x.homeGoals;gf+=a;ga+=b;if(a>b)w++;else if(a===b)d++;else l++});return {team,played,w,d,l,gf,ga,points:w*3+d}}).sort((a:Obj,b:Obj)=>b.points-a.points||(b.gf-b.ga)-(a.gf-a.ga)||b.gf-a.gf||b.w-a.w||a.team.name.localeCompare(b.team.name,'pt-BR'));
